pts.N = { V: 2.1, p: CTh / 2.1 };
// adiabat through N: p*V^gam = const; O on Tc isotherm
var kN = pts.N.p * Math.pow(pts.N.V, gam);
var VO = Math.pow(kN / CTc, 1 / (gam - 1));
pts.O = { V: VO, p: CTc / VO };
pts.P = { V: 2.1, p: CTc / 2.1 };
// scale P so adiabat P->M closes (approx; fine for demo)

function pvPlot() {
  var x0 = 90, y0 = 420, w = 560, h = 360;
  var Vmin = 0.5, Vmax = 6.5, pmin = 0, pmax = 6;
  return {
    X: function (V) { return x0 + (V - Vmin) / (Vmax - Vmin) * w; },
    Y: function (p) { return y0 - (p - pmin) / (pmax - pmin) * h; }
  };
}

