var W = 760, H = 480;
var draw = SVG().addTo('#container').size('100%', '100%').viewbox(0, 0, W, H);

var state = { step: 'M→N', contact: 'Isothermal (reservoir)', view: 'Piston panels' };
var steps = ['M→N', 'N→O', 'O→P', 'P→M'];
var demoSteps = [
  { title: 'Step 1: Isothermal expansion (M→N)', narration: 'The cylinder sits in the hot reservoir at Th. Heat Qh flows in and the gas expands at constant temperature, pushing the piston up and doing work W1 on the surroundings.', state: { stepState: 'M→N', thermalContact: 'Isothermal (reservoir)', viewMode: 'Piston panels' } },
  { title: 'Step 2: Adiabatic expansion (N→O)', narration: 'Now surrounded by insulation, no heat can cross the boundary. The gas keeps expanding and lifting the piston (W2 up), but the energy comes from its own internal energy, so it cools from Th to Tc.', state: { stepState: 'N→O', thermalContact: 'Adiabatic (insulated)', viewMode: 'Piston panels' } },
  { title: 'Step 3: Isothermal compression (O→P)', narration: 'In contact with the cold reservoir at Tc, work W3 is done on the gas and the expelled energy leaves as heat Qc, keeping the temperature constant while the volume shrinks.', state: { stepState: 'O→P', thermalContact: 'Isothermal (reservoir)', viewMode: 'Piston panels' } },
  { title: 'Step 4: Adiabatic compression (P→M)', narration: 'Insulated again, work W4 compresses the gas with no heat exchange; the compression work warms it back from Tc to Th, returning it exactly to state M and closing the cycle.', state: { stepState: 'P→M', thermalContact: 'Adiabatic (insulated)', viewMode: 'Piston panels' } },
  { title: 'Map to the p-V loop', narration: 'Switching to the p-V view, the four piston states appear as corners M, N, O, P of a closed loop: two isotherms at Th and Tc joined by two adiabats, traversed clockwise. Step through the cycle again and watch each segment highlight.', state: { stepState: 'M→N', thermalContact: 'Isothermal (reservoir)', viewMode: 'p-V path' } }
];
var curStep = 0;

var stepMeta = [
  { label: 'Step 1:', name: 'Isothermal expansion', trans: '(M→N)', color: '#e59898', block: 'Reservoir', sub: '(Temperature Th)', h: 180, heat: 'Qh up', work: 'W1', workDir: -1, tip: 'Isothermal expansion: Qh enters from the hot reservoir, gas expands and does work.' },
  { label: 'Step 2:', name: 'Adiabatic expansion', trans: '(N→O)', color: '#f0e2d8', block: 'Insulation', sub: '', h: 290, heat: null, work: 'W2', workDir: -1, tip: 'Adiabatic expansion: insulated, gas cools from Th to Tc while expanding.' },
  { label: 'Step 3:', name: 'Isothermal compression', trans: '(O→P)', color: '#a8c8dc', block: 'Reservoir', sub: '(Temperature Tc)', h: 270, heat: 'Qc down', work: 'W3', workDir: 1, tip: 'Isothermal compression: Qc leaves to the cold reservoir as work compresses the gas.' },
  { label: 'Step 4:', name: 'Adiabatic compression', trans: '(P→M)', color: '#f0e2d8', block: 'Insulation', sub: '', h: 120, heat: null, work: 'W4', workDir: 1, tip: 'Adiabatic compression: insulated, gas warms from Tc back to Th, closing the cycle.' }
];

// deterministic stipple
var dots = [];
(function () { var s = 12345; for (var i = 0; i < 700; i++) { s = (s * 1103515245 + 12345) & 0x7fffffff; var a = s / 0x7fffffff; s = (s * 1103515245 + 12345) & 0x7fffffff; dots.push([a, s / 0x7fffffff]); } })();

var panelsGroup = draw.group();
var pvGroup = draw.group();

function arrow(g, x1, y1, x2, y2, color, wdt) {
  g.line(x1, y1, x2, y2).stroke({ color: color, width: wdt, linecap: 'round' });
  var ang = Math.atan2(y2 - y1, x2 - x1);
  var hl = 4 + wdt * 1.2;
  g.polygon([
    [x2, y2],
    [x2 - hl * Math.cos(ang - 0.45), y2 - hl * Math.sin(ang - 0.45)],
    [x2 - hl * Math.cos(ang + 0.45), y2 - hl * Math.sin(ang + 0.45)]
  ].map(function (p) { return p[0] + ',' + p[1]; }).join(' ')).fill(color);
}

function drawPanels() {
  panelsGroup.clear();
  var activeIdx = steps.indexOf(state.step);
  var top = 10, blockH = 340, panelW = 170, gap = 14, cylW = 62;
  for (var i = 0; i < 4; i++) {
    var m = stepMeta[i];
    var x0 = 12 + i * (panelW + gap);
    var active = (i === activeIdx);
    var g = panelsGroup.group().opacity(active ? 1 : 0.45);
    (function (idx, gg) {
      gg.css('cursor', 'pointer');
      gg.on('mousemove', function (e) { showTooltip(stepMeta[idx].label + ' ' + stepMeta[idx].name, e); });
      gg.on('mouseleave', function () { hideTooltip(); });
      gg.on('click', function () { showPopup(stepMeta[idx].label + ' ' + stepMeta[idx].name, stepMeta[idx].tip); update_stepState(steps[idx]); });
    })(i, g);
    g.rect(panelW, blockH).move(x0, top).fill(m.color).stroke({ color: '#888', width: 1 });
    // cylinder
    var cx = x0 + panelW / 2 - cylW / 2, cylTop = top + 55, cylH = blockH - 55;
    g.rect(cylW, cylH).move(cx, cylTop).fill('#fff').stroke({ color: '#555', width: 1.5 });
    // gas
    var gh = m.h;
    var gy = cylTop + cylH - gh;
    g.rect(cylW - 4, gh).move(cx + 2, gy).fill('#cfcfcf');
    for (var d = 0; d < dots.length; d++) {
      var dx = cx + 5 + dots[d][0] * (cylW - 10), dy = gy + 3 + dots[d][1] * (gh - 6);
      if (dy < cylTop + cylH - 3) g.circle(2.2).center(dx, dy).fill('#666');
    }
    // piston
    g.rect(cylW - 2, 9).move(cx + 1, gy - 9).fill('#a8a8a8').stroke({ color: '#666', width: 1 });
    var stemX = x0 + panelW / 2;
    g.rect(7, gy - 9 - (cylTop - 18)).move(stemX - 3.5, cylTop - 18).fill('#b5b5b5').stroke({ color: '#777', width: 1 });
    // work arrow beside stem
    var wLen = 42, wy = cylTop + 6;
    if (active) {
      var wy2 = wy + m.workDir * wLen;
      arrow(g, stemX - 16, wy, stemX - 16, wy2, '#3c9a3c', 2.5);
      g.plain(m.work).font({ size: 14, weight: 'bold', family: 'sans-serif' }).fill('#2a7a2a')
        .attr({ 'text-anchor': 'middle' }).center(stemX - 16, wy2 + (m.workDir < 0 ? -12 : 12));
    }
    // heat arrow
    if (active && m.heat) {
      var hy = cylTop + cylH + 30;
      if (m.heat === 'Qh up') {
        arrow(g, stemX, hy, stemX, cylTop + cylH + 6, '#777', 5);
        g.plain('Qh').font({ size: 14, weight: 'bold', family: 'sans-serif' }).fill('#555').attr({ 'text-anchor': 'middle' }).center(stemX, hy + 12);
      } else {
        arrow(g, stemX, cylTop + cylH + 6, stemX, hy, '#777', 5);
        g.plain('Qc').font({ size: 14, weight: 'bold', family: 'sans-serif' }).fill('#555').attr({ 'text-anchor': 'middle' }).center(stemX, hy + 12);
      }
    }
    // block labels
    g.plain(m.block).font({ size: 13, weight: 'bold', family: 'sans-serif' }).fill('#333').attr({ 'text-anchor': 'middle' }).center(x0 + panelW / 2, top + blockH - 34);
    if (m.sub) g.plain(m.sub).font({ size: 11, family: 'sans-serif' }).fill('#333').attr({ 'text-anchor': 'middle' }).center(x0 + panelW / 2, top + blockH - 16);
    // caption
    g.plain(m.label).font({ size: 13, weight: 'bold', family: 'sans-serif' }).fill('#000').attr({ 'text-anchor': 'middle' }).center(x0 + panelW / 2, top + blockH + 58);
    g.plain(m.name).font({ size: 13, weight: 'bold', family: 'sans-serif' }).fill('#000').attr({ 'text-anchor': 'middle' }).center(x0 + panelW / 2, top + blockH + 74);
    g.plain(m.trans).font({ size: 13, weight: 'bold', family: 'sans-serif' }).fill('#000').attr({ 'text-anchor': 'middle' }).center(x0 + panelW / 2, top + blockH + 90);
  }
}

// p-V loop: V from 1 to 5, isotherms p=C/V
var CTh = 5.2, CTc = 2.6, gam = 1.4;
var VM = CTh / 5.0 * 1.0; // M at p=5 -> V=1.04
var pts = {};
pts.M = { V: 1.05, p: CTh / 1.05 };
pts.N = { V: 2.1, p: CTh / 2.1 };
// adiabat through N: p*V^gam = const; O on Tc isotherm
var kN = pts.N.p * Math.pow(pts.N.V, gam);
var VO = Math.pow(kN / CTc, 1 / (gam - 1));
pts.O = { V: VO, p: CTc / VO };
pts.P = { V: 2.1, p: CTc / 2.1 };
// scale P so adiabat P->M closes (approx; fine for demo)

function pvPlot() {
  var x0 = 90, y0 = 420, w = 560, h = 360;
  var Vmin = 0.5, Vmax = 6.5, pmin = 0, pmax = 6;
  return {
    X: function (V) { return x0 + (V - Vmin) / (Vmax - Vmin) * w; },
    Y: function (p) { return y0 - (p - pmin) / (pmax - pmin) * h; }
  };
}

function pathSeg(f, a, b, color, wdt, dashed) {
  var str = '';
  for (var i = 0; i <= 30; i++) {
    var V = a + (b - a) * i / 30, p = f(V);
    str += (i === 0 ? 'M' : 'L') + V.toFixed(3) + ',' + p.toFixed(3);
  }
  return { d: str, color: color, wdt: wdt, dashed: dashed };
}

function drawPV() {
  pvGroup.clear();
  var pv = pvPlot();
  var activeIdx = steps.indexOf(state.step);
  // axes
  pvGroup.line(pv.X(0.5), pv.Y(0), pv.X(6.5), pv.Y(0)).stroke({ color: '#000', width: 2 });
  pvGroup.line(pv.X(0.5), pv.Y(0), pv.X(0.5), pv.Y(6)).stroke({ color: '#000', width: 2 });
  pvGroup.plain('V').font({ size: 16, weight: 'bold', family: 'sans-serif' }).move(pv.X(6.5) + 8, pv.Y(0) - 8);
  pvGroup.plain('p').font({ size: 16, weight: 'bold', family: 'sans-serif' }).move(pv.X(0.5) - 18, pv.Y(6) - 6);

  var kN = pts.N.p * Math.pow(pts.N.V, gam);
  var kP = pts.P.p * Math.pow(pts.P.V, gam);
  var segs = [
    { from: 'M', to: 'N', f: function (V) { return CTh / V; }, a: pts.M.V, b: pts.N.V, name: 'Step 1: isothermal expansion at Th (heat Qh in)' },
    { from: 'N', to: 'O', f: function (V) { return kN / Math.pow(V, gam); }, a: pts.N.V, b: pts.O.V, name: 'Step 2: adiabatic expansion, Th → Tc (no heat)' },
    { from: 'O', to: 'P', f: function (V) { return CTc / V; }, a: pts.O.V, b: pts.P.V, name: 'Step 3: isothermal compression at Tc (heat Qc out)' },
    { from: 'P', to: 'M', f: function (V) { return kP / Math.pow(V, gam); }, a: pts.P.V, b: pts.M.V, name: 'Step 4: adiabatic compression, Tc → Th (no heat)' }
  ];
  segs.forEach(function (s, i) {
    var active = (i === activeIdx);
    var col = active ? '#d33' : '#1f77b4';
    var d = '', ptsArr = [];
    for (var j = 0; j <= 40; j++) {
      var V = s.a + (s.b - s.a) * j / 40, p = s.f(V);
      ptsArr.push(pv.X(V) + ',' + pv.Y(p));
    }
    var pl = pvGroup.polyline(ptsArr.join(' ')).fill('none')
      .stroke({ color: col, width: active ? 4 : 2, linecap: 'round' });
    if (!active) pl.opacity(0.7);
    pl.css('cursor', 'pointer');
    pl.on('mousemove', function (e) { showTooltip(s.from + '→' + s.to, e); });
    pl.on('mouseleave', function () { hideTooltip(); });
    pl.on('click', function () { showPopup(s.from + '→' + s.to, s.name); update_stepState(steps[i]); });
    // direction arrowhead at midpoint
    var Vm = (s.a + s.b) / 2, pm = s.f(Vm);
    var eps = 0.02 * (s.b - s.a > 0 ? 1 : -1);
    var p2 = s.f(Vm + eps);
    var ang = Math.atan2(pv.Y(p2) - pv.Y(pm), pv.X(Vm + eps) - pv.X(Vm));
    var hl = 9, mx = pv.X(Vm), my = pv.Y(pm);
    pvGroup.polygon([[mx, my], [mx - hl * Math.cos(ang - 0.45), my - hl * Math.sin(ang - 0.45)], [mx - hl * Math.cos(ang + 0.45), my - hl * Math.sin(ang + 0.45)]]
      .map(function (q) { return q[0] + ',' + q[1]; }).join(' ')).fill(active ? '#d33' : '#1f77b4');
  });
  // corner points
  ['M', 'N', 'O', 'P'].forEach(function (k) {
    var pt = pts[k], active = (steps[activeIdx][0] === k);
    pvGroup.circle(9).center(pv.X(pt.V), pv.Y(pt.p)).fill(active ? '#d33' : '#333').stroke({ color: '#fff', width: 1.5 });
    pvGroup.plain(k).font({ size: 15, weight: 'bold', family: 'sans-serif' }).fill('#000')
      .attr({ 'text-anchor': 'middle' }).center(pv.X(pt.V) + (k === 'N' || k === 'P' ? 14 : -14), pv.Y(pt.p) - 4);
  });
  // isotherm labels
  pvGroup.plain('Th').font({ size: 13, weight: 'bold', family: 'sans-serif' }).fill('#b22').center(pv.X(1.35), pv.Y(CTh / 1.35) + 14);
  pvGroup.plain('Tc').font({ size: 13, weight: 'bold', family: 'sans-serif' }).fill('#226').center(pv.X(1.2), pv.Y(CTc / 1.2) + 30);
  pvGroup.plain('Net work = enclosed area (clockwise cycle)').font({ size: 13, family: 'sans-serif' }).fill('#555')
    .attr({ 'text-anchor': 'middle' }).center(400, 455);
}

function render() {
  if (state.view === 'Piston panels') {
    panelsGroup.show(); pvGroup.hide(); drawPanels();
  } else {
    panelsGroup.hide(); pvGroup.show(); drawPV();
  }
}

function update_stepState(v) {
  state.step = v;
  document.getElementById('stepStateInput').value = v;
  var i = steps.indexOf(v);
  state.contact = (i === 0 || i === 2) ? 'Isothermal (reservoir)' : 'Adiabatic (insulated)';
  document.getElementById('thermalContactInput').checked = (state.contact === 'Isothermal (reservoir)');
  render();
}
function toggle_thermalContact(on) {
  state.contact = on ? 'Isothermal (reservoir)' : 'Adiabatic (insulated)';
  var i = steps.indexOf(state.step);
  var shouldRes = (i === 0 || i === 2);
  if (on !== shouldRes) {
    var next = on ? 0 : 1;
    state.step = steps[next];
    document.getElementById('stepStateInput').value = state.step;
  }
  render();
}
function toggle_viewMode(on) {
  state.view = on ? 'p-V path' : 'Piston panels';
  render();
}

function applyStep(i) {
  curStep = ((i % demoSteps.length) + demoSteps.length) % demoSteps.length;
  var s = demoSteps[curStep];
  document.getElementById('demoNarration').textContent = s.title + ' — ' + s.narration;
  document.getElementById('stepLabel').textContent = (curStep + 1) + ' / ' + demoSteps.length;
  state.step = s.state.stepState;
  state.contact = s.state.thermalContact;
  state.view = s.state.viewMode;
  document.getElementById('stepStateInput').value = state.step;
  document.getElementById('thermalContactInput').checked = (state.contact === 'Isothermal (reservoir)');
  document.getElementById('viewModeInput').checked = (state.view === 'p-V path');
  render();
}
function nextStep() {
  if (state.view === 'p-V path' && curStep === demoSteps.length - 1) {
    // cycle through segments on p-V view
    var i = (steps.indexOf(state.step) + 1) % 4;
    update_stepState(steps[i]);
    document.getElementById('demoNarration').textContent = 'Segment ' + steps[i] + ' highlighted on the loop.';
    return;
  }
  applyStep(curStep + 1);
}
function prevStep() { applyStep(curStep - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: The Carnot cycle is a sequence of four reversible processes — isothermal expansion, adiabatic expansion, isothermal compression, adiabatic compression — in which heat crosses the system boundary only during the two isothermal steps while the gas is in contact with a reservoir, and the four piston states M, N, O, P trace a closed loop on a p-V diagram.
KEY INSIGHT (what students should walk away understanding): Heat flows only during the two isothermal steps (Qh in at Th, Qc out at Tc) while the adiabatic steps merely shuttle the gas between those two temperatures, and the net work output is the area enclosed by the closed MNOP loop on the p-V diagram.
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "The Carnot cycle is a sequence of four reversible processes — isothermal expansion, adiabatic expansion, isothermal compression, adiabatic compression — in which heat crosses the system boundary only during the two isothermal steps while the gas is in contact with a reservoir, and the four piston states M, N, O, P trace a closed loop on a p-V diagram.",
  "figureType": "diagram",
  "elements": [
    "four side-by-side cylinder-and-piston panels, one per step",
    "gray gas region stippled with dots inside each cylinder, column height tall in steps 2-3, medium in step 1, shortest in step 4",
    "piston cap with vertical stem rising from the open top of each cylinder",
    "red surroundings block for step 1 labeled 'Reservoir' and '(Temperature Th)'",
    "pale surroundings block for step 2 labeled 'Insulation'",
    "blue surroundings block for step 3 labeled 'Reservoir' and '(Temperature Tc)'",
    "pale surroundings block for step 4 labeled 'Insulation'",
    "thick gray heat arrow Qh pointing upward into the gas in step 1",
    "thick gray heat arrow Qc pointing downward out of the gas in step 3",
    "green work arrows W1 (up) and W2 (up) on the piston stems of steps 1-2",
    "green work arrows W3 (down) and W4 (down) on the piston stems of steps 3-4",
    "bold captions: 'Step 1: Isothermal expansion (M→N)', 'Step 2: Adiabatic expansion (N→O)', 'Step 3: Isothermal compression (O→P)', 'Step 4: Adiabatic compression (P→M)'",
    "p-V path view: vertical p axis, horizontal V axis, closed MNOP cycle curve with two curved isotherms (Th upper, Tc lower) connected by two steeper adiabats, corner points labeled M, N, O, P, clockwise direction arrows on the curve"
  ],
  "interactions": [
    {
      "id": "stepState",
      "type": "button",
      "label": "Cycle step",
      "states": [
        "M→N",
        "N→O",
        "O→P",
        "P→M"
      ],
      "default": "M→N",
      "teaches": "The four processes happen in a fixed order — expansion then compression — and each step changes the gas volume, the work direction, and whether heat flows, returning the system to its starting state M"
    },
    {
      "id": "thermalContact",
      "type": "toggle",
      "label": "Boundary condition",
      "options": [
        "Isothermal (reservoir)",
        "Adiabatic (insulated)"
      ],
      "default": "Isothermal (reservoir)",
      "teaches": "Heat crosses the boundary only when the cylinder sits in a reservoir (steps 1 and 3, Qh in and Qc out); inside insulation (steps 2 and 4) no heat flows and temperature change comes entirely from work"
    },
    {
      "id": "viewMode",
      "type": "toggle",
      "label": "Representation",
      "options": [
        "Piston panels",
        "p-V path"
      ],
      "default": "Piston panels",
      "teaches": "Each physical piston position corresponds to one corner of the closed MNOP loop on the p-V diagram, and each process corresponds to one segment of that loop, so the mechanical motion and the thermodynamic cycle are the same thing seen two ways"
    }
  ],
  "demo_steps": [
    {
      "title": "Step 1: Isothermal expansion (M→N)",
      "narration": "The cylinder sits in the hot reservoir at Th. Heat Qh flows in and the gas expands at constant temperature, pushing the piston up and doing work W1 on the surroundings.",
      "state": {
        "stepState": "M→N",
        "thermalContact": "Isothermal (reservoir)",
        "viewMode": "Piston panels"
      }
    },
    {
      "title": "Step 2: Adiabatic expansion (N→O)",
      "narration": "Now surrounded by insulation, no heat can cross the boundary. The gas keeps expanding and lifting the piston (W2 up), but the energy comes from its own internal energy, so it cools from Th to Tc.",
      "state": {
        "stepState": "N→O",
        "thermalContact": "Adiabatic (insulated)",
        "viewMode": "Piston panels"
      }
    },
    {
      "title": "Step 3: Isothermal compression (O→P)",
      "narration": "In contact with the cold reservoir at Tc, work W3 is done on the gas and the expelled energy leaves as heat Qc, keeping the temperature constant while the volume shrinks.",
      "state": {
        "stepState": "O→P",
        "thermalContact": "Isothermal (reservoir)",
        "viewMode": "Piston panels"
      }
    },
    {
      "title": "Step 4: Adiabatic compression (P→M)",
      "narration": "Insulated again, work W4 compresses the gas with no heat exchange; the compression work warms it back from Tc to Th, returning it exactly to state M and closing the cycle.",
      "state": {
        "stepState": "P→M",
        "thermalContact": "Adiabatic (insulated)",
        "viewMode": "Piston panels"
      }
    },
    {
      "title": "Map to the p-V loop",
      "narration": "Switching to the p-V view, the four piston states appear as corners M, N, O, P of a closed loop: two isotherms at Th and Tc joined by two adiabats, traversed clockwise. Step through the cycle again and watch each segment highlight.",
      "state": {
        "stepState": "M→N",
        "thermalContact": "Isothermal (reservoir)",
        "viewMode": "p-V path"
      }
    }
  ],
  "keyInsight": "Heat flows only during the two isothermal steps (Qh in at Th, Qc out at Tc) while the adiabatic steps merely shuttle the gas between those two temperatures, and the net work output is the area enclosed by the closed MNOP loop on the p-V diagram.",
  "reconstructionNotes": "Four vertical panels in a row, each a tall colored block filling most of the panel height with a centered white cylinder cut into it. Block colors: warm red (step 1), pale neutral beige (steps 2 and 4), cool blue (step 3). Gas rendered as a light gray fill with a dense random dot stipple; piston as a darker gray horizontal cap with a narrow vertical stem. Heat arrows thick and gray, work arrows thinner and green, placed beside the piston stem. Arrow directions: W1, W2 up; W3, W4 down; Qh up into the gas; Qc down out of it. Gas column heights rank step 2 ≈ step 3 (tallest) > step 1 > step 4 (shortest) to reflect the volume changes. Bold black captions centered under each panel in three lines: step number and process name, then the (X→Y) transition. Only the active step's panel is fully saturated and its arrows emphasized; inactive panels dimmed. For the p-V path view, replace the four panels with a single p-V axes plot: two smooth convex isotherm curves (upper labeled Th, lower labeled Tc) connected by steeper adiabat segments, corner points M (high p, low V), N, O (low p, high V), P marked with dots and labels, small clockwise arrowheads along the loop, and the segment matching the current stepState drawn thicker and brighter."
}

The second image above is a screenshot of the PREVIOUS attempt's rendered output (not the source figure) — use it to see exactly what broke.

systemPrompt:
You are a strict critic of generated inline-interactive 2D figures (SVG.js / Chart.js / Mermaid) against the original 2D textbook figure image.
You will receive the original source figure image, the generated HTML/JavaScript code, and a rendered screenshot of the generated HTML (if screenshot capture succeeds). Start by using the screenshot to help evaluate the faithfulness of the generated figure to the source figure, listing discrepancies in the primitive elements between what you see in the source figure versus what you see in the generated figure. If the screenshot was not received, mention this in the notes.
Score the generated figure using the rubric and give feedback to improve the figure. Be critical and honest — err toward lower scores when in doubt. The default (step-0) state should read as a drop-in replacement for the static source image. Do not give credit for things that are absent or barely present. Output ONLY a valid JSON object — no explanation, no markdown, no fences.

AUTOMATED VERIFICATION ALREADY PASSED. A deterministic verifier has rendered this figure headless at multiple viewports and confirmed it runs without exceptions or page errors, produces a visible visual root (SVG, canvas, or Mermaid diagram) containing real text or graphics rather than an empty frame, and fits the viewport with no horizontal overflow and the main visual unclipped at wide widths.
Spend NO scores, failure modes, discrepancies, or action items on any of that. Focus ENTIRELY on SEMANTIC FIDELITY to the source: correct 2D structure, correct mark types, faithful composition and colors, correct and meaningful labels, meaningful and conceptually-correct interactions, and concept accuracy. Judge whether it is the *right* figure and a good teaching artifact — not whether it renders.
IMPORTANT — the 2D verifier performs NO label checks at all: no on-screen check, no size check, no overlap check. Label placement is fully IN SCOPE for you. Do flag labels that collide with each other or the artwork, escape the plot area, are clipped at the edge, or are too small to read comfortably at inline size.

SCAFFOLD CONTEXT (provided automatically — do not penalise for missing these):
