/* p-V parametrization: constants chosen so the loop closes exactly.
 * Isotherms p = CTh/V and p = CTc/V; adiabats p·V^γ = const.
 * V_M=1, V_N=2 → V_P = V_M·r^(1/(γ-1)), V_O = V_N·r^(1/(γ-1)), r = CTh/CTc.
 * Adiabat P→M passes through M and terminates at M by construction. */
var gam = 1.4, CTh = 4.0, CTc = 2.4;
var r = CTh / CTc, stretch = Math.pow(r, 1 / (gam - 1));
var pts = {
  M: { V: 1.0, p: CTh / 1.0 },
  N: { V: 2.0, p: CTh / 2.0 }
};
pts.P = { V: 1.0 * stretch, p: CTc / (1.0 * stretch) };
pts.O = { V: 2.0 * stretch, p: CTc / (2.0 * stretch) };
var kM = pts.M.p * Math.pow(pts.M.V, gam); // adiabat through M and P
var kN = pts.N.p * Math.pow(pts.N.V, gam); // adiabat through N and O

var Vmin = 0.4, Vmax = pts.O.V + 0.6, pmin = 0, pmax = CTh / Vmin * 0.92;
function pvPlot() {
  var x0 = 80, y0 = 420, w = 580, h = 370;
  return {
    X: function (V) { return x0 + (V - Vmin) / (Vmax - Vmin) * w; },
    Y: function (p) { return y0 - (p - pmin) / (pmax - pmin) * h; }
  };
}

function drawPV() {
  pvGroup.clear();
  var pv = pvPlot();
  var activeIdx = steps.indexOf(state.step);
  // axes
  pvGroup.line(pv.X(Vmin), pv.Y(0), pv.X(Vmax), pv.Y(0)).stroke({ color: '#000', width: 2 });
  pvGroup.line(pv.X(Vmin), pv.Y(0), pv.X(Vmin), pv.Y(pmax)).stroke({ color: '#000', width: 2 });
  pvGroup.plain('V').font({ size: 16, weight: 'bold', family: 'sans-serif' }).move(pv.X(Vmax) + 6, pv.Y(0) - 9);
  pvGroup.plain('p').font({ size: 16, weight: 'bold', family: 'sans-serif' }).move(pv.X(Vmin) - 20, pv.Y(pmax) - 8);

  var segs = [
    { from: 'M', to: 'N', f: function (V) { return CTh / V; }, a: pts.M.V, b: pts.N.V, name: 'Isothermal expansion at Th: heat Qh flows in, gas expands and does work.' },
    { from: 'N', to: 'O', f: function (V) { return kN / Math.pow(V, gam); }, a: pts.N.V, b: pts.O.V, name: 'Adiabatic expansion: no heat flow; the gas cools from Th to Tc as it expands.' },
    { from: 'O', to: 'P', f: function (V) { return CTc / V; }, a: pts.O.V, b: pts.P.V, name: 'Isothermal compression at Tc: work in, heat Qc flows out.' },
    { from: 'P', to: 'M', f: function (V) { return kM / Math.pow(V, gam); }, a: pts.P.V, b: pts.M.V, name: 'Adiabatic compression: no heat flow; work warms the gas from Tc back to Th.' }
  ];
  // shaded enclosed area (net work)
  var areaPts = [];
  var si;
  for (si = 0; si < 4; si++) {
    for (var j = 0; j <= 30; j++) {
      var V = segs[si].a + (segs[si].b - segs[si].a) * j / 30;
      areaPts.push(pv.X(V) + ',' + pv.Y(segs[si].f(V)));
    }
  }
  pvGroup.polygon(areaPts.join(' ')).fill({ color: '#ffd24d', opacity: 0.25 }).stroke('none');

  segs.forEach(function (s, i) {
    var active = (i === activeIdx);
    var col = active ? '#d33' : '#1f77b4';
    var ptsArr = [];
    for (var j = 0; j <= 40; j++) {
      var V = s.a + (s.b - s.a) * j / 40, p = s.f(V);
      ptsArr.push(pv.X(V) + ',' + pv.Y(p));
    }
    var pl = pvGroup.polyline(ptsArr.join(' ')).fill('none')
      .stroke({ color: col, width: active ? 4.5 : 2, linecap: 'round' });
    if (!active) pl.opacity(0.75);
    pl.css('cursor', 'pointer');
    pl.on('mousemove', function (e) { showTooltip(s.from + '→' + s.to, e); });
    pl.on('mouseleave', function () { hideTooltip(); });
    pl.on('click', function () { showPopup(s.from + '→' + s.to, s.name); update_stepState(steps[i]); });
    // clockwise direction arrowhead at segment midpoint
    var Vm = (s.a + s.b) / 2, pm = s.f(Vm);
    var eps = 0.02 * (s.b - s.a);
    var p2 = s.f(Vm + eps);
    var ang = Math.atan2(pv.Y(p2) - pv.Y(pm), pv.X(Vm + eps) - pv.X(Vm));
    var hl = 9, mx = pv.X(Vm), my = pv.Y(pm);
    pvGroup.polygon([[mx, my], [mx - hl * Math.cos(ang - 0.45), my - hl * Math.sin(ang - 0.45)], [mx - hl * Math.cos(ang + 0.45), my - hl * Math.sin(ang + 0.45)]]
      .map(function (q) { return q[0] + ',' + q[1]; }).join(' ')).fill(active ? '#d33' : '#1f77b4');
  });
  // corner points with halo labels placed in open space
  var labelOff = { M: [-10, -12], N: [14, -12], O: [14, 10], P: [12, 12] };
  ['M', 'N', 'O', 'P'].forEach(function (k) {
    var pt = pts[k];
    pvGroup.circle(9).center(pv.X(pt.V), pv.Y(pt.p)).fill('#333').stroke({ color: '#fff', width: 1.5 });
    pvGroup.plain(k).font({ size: 15, weight: 'bold', family: 'sans-serif' }).fill('#000')
      .attr({ 'text-anchor': 'middle', 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' })
      .center(pv.X(pt.V) + labelOff[k][0], pv.Y(pt.p) + labelOff[k][1]);
  });
  // isotherm labels in open space right of curves
  pvGroup.plain('Th').font({ size: 13, weight: 'bold', family: 'sans-serif' }).fill('#b22222')
    .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' })
    .center(pv.X(1.15), pv.Y(CTh / 1.15) - 14);
  pvGroup.plain('Tc').font({ size: 13, weight: 'bold', family: 'sans-serif' }).fill('#2244aa')
    .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' })
    .center(pv.X(1.0), pv.Y(CTc / 1.0) + 20);
  pvGroup.plain('Net work = enclosed area (clockwise cycle)').font({ size: 13, family: 'sans-serif' }).fill('#555')
    .attr({ 'text-anchor': 'middle' }).center(370, 462);
}

function render() {
  if (state.view === 'Piston panels') {
    panelsGroup.show(); pvGroup.hide(); drawPanels();
  } else {
    panelsGroup.hide(); pvGroup.show(); drawPV();
  }
}

function update_stepState(v) {
  state.step = v;
  document.getElementById('stepStateInput').value = v;
  var i = steps.indexOf(v);
  state.contact = (i === 0 || i === 2) ? 'Isothermal (reservoir)' : 'Adiabatic (insulated)';
  document.getElementById('thermalContactInput').checked = (state.contact === 'Isothermal (reservoir)');
  render();
}
function toggle_thermalContact(on) {
  state.contact = on ? 'Isothermal (reservoir)' : 'Adiabatic (insulated)';
  var i = steps.indexOf(state.step);
  var shouldRes = (i === 0 || i === 2);
  if (on !== shouldRes) {
    var next = on ? 0 : 1;
    state.step = steps[next];
    document.getElementById('stepStateInput').value = state.step;
  }
  render();
}
function toggle_viewMode(on) {
  state.view = on ? 'p-V path' : 'Piston panels';
  render();
}

function applyStep(i) {
  curStep = ((i % demoSteps.length) + demoSteps.length) % demoSteps.length;
  var s = demoSteps[curStep];
  document.getElementById('demoNarration').textContent = s.title + ' — ' + s.narration;
  document.getElementById('stepLabel').textContent = (curStep + 1) + ' / ' + demoSteps.length;
  state.step = s.state.stepState;
  state.contact = s.state.thermalContact;
  state.view = s.state.viewMode;
  document.getElementById('stepStateInput').value = state.step;
  document.getElementById('thermalContactInput').checked = (state.contact === 'Isothermal (reservoir)');
  document.getElementById('viewModeInput').checked = (state.view === 'p-V path');
  render();
}
function nextStep() {
  if (state.view === 'p-V path' && curStep === demoSteps.length - 1) {
    var i = (steps.indexOf(state.step) + 1) % 4;
    update_stepState(steps[i]);
    document.getElementById('demoNarration').textContent = 'Segment ' + steps[i] + ' highlighted on the loop — notice each piston process is one side of the closed cycle.';
    return;
  }
  applyStep(curStep + 1);
}
function prevStep() { applyStep(curStep - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

