userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<p id="demoNarration" style="margin:0;font-size:10px;max-width:180px">Loading…</p>
<div style="display:flex;gap:4px;align-items:center">
  <button onclick="prevStep()">◀</button>
  <span id="stepLabel">1 / 4</span>
  <button onclick="nextStep()">▶</button>
</div>
<label>Cycle step:
  <select id="stepStateInput" onchange="update_stepState(this.value)">
    <option value="M→N" selected>M→N</option>
    <option value="N→O">N→O</option>
    <option value="O→P">O→P</option>
    <option value="P→M">P→M</option>
  </select>
</label>
<label><input id="thermalContactInput" type="checkbox" checked onchange="toggle_thermalContact(this.checked)"> Boundary: Isothermal (reservoir) — uncheck for Adiabatic (insulated)</label>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var W = 780, H = 470;
var draw = SVG().addTo('#container').size('100%', '100%').viewbox(0, 0, W, H);

var state = { step: 'M→N', contact: 'Isothermal (reservoir)' };
var steps = ['M→N', 'N→O', 'O→P', 'P→M'];

var demoSteps = [
  { title: 'Step 1: Isothermal expansion (M→N)', narration: 'The cylinder sits in the hot reservoir at Th. Heat Qh flows in and the gas expands at constant temperature, pushing the piston up and doing work W1 on the surroundings.', state: { stepState: 'M→N', thermalContact: 'Isothermal (reservoir)' } },
  { title: 'Step 2: Adiabatic expansion (N→O)', narration: 'Now surrounded by insulation, no heat can cross the boundary. The gas keeps expanding and lifting the piston (W2 up), but the energy comes from its own internal energy, so it cools from Th to Tc.', state: { stepState: 'N→O', thermalContact: 'Adiabatic (insulated)' } },
  { title: 'Step 3: Isothermal compression (O→P)', narration: 'In contact with the cold reservoir at Tc, work W3 is done on the gas and the expelled energy leaves as heat Qc, keeping the temperature constant while the volume shrinks.', state: { stepState: 'O→P', thermalContact: 'Isothermal (reservoir)' } },
  { title: 'Step 4: Adiabatic compression (P→M)', narration: 'Insulated again, work W4 compresses the gas with no heat exchange; the compression work warms it back from Tc to Th, returning it exactly to state M and closing the cycle.', state: { stepState: 'P→M', thermalContact: 'Adiabatic (insulated)' } }
];
var curStep = 0;

var stepMeta = [
  { label: 'Step 1:', name: 'Isothermal expansion', trans: '(M→N)', color: '#d96b6b', boundary: 'iso', block: 'Reservoir', sub: '(Temperature Th)', h: 120, heat: 'Qh', heatDir: -1, work: 'W1', workDir: -1, tip: 'Isothermal expansion: the gas sits in the hot reservoir at Th. Heat Qh flows in, the gas expands at constant temperature, and it does work W1 on the surroundings.' },
  { label: 'Step 2:', name: 'Adiabatic expansion', trans: '(N→O)', color: '#efe3d5', boundary: 'adi', block: 'Insulation', sub: '', h: 205, heat: null, work: 'W2', workDir: -1, tip: 'Adiabatic expansion: insulated, so no heat flows. The gas expands and does work W2 using its own internal energy, cooling from Th to Tc.' },
  { label: 'Step 3:', name: 'Isothermal compression', trans: '(O→P)', color: '#7fa8c9', boundary: 'iso', block: 'Reservoir', sub: '(Temperature Tc)', h: 185, heat: 'Qc', heatDir: 1, work: 'W3', workDir: 1, tip: 'Isothermal compression: in the cold reservoir at Tc, work W3 is done on the gas and that energy leaves as heat Qc at constant temperature.' },
  { label: 'Step 4:', name: 'Adiabatic compression', trans: '(P→M)', color: '#efe3d5', boundary: 'adi', block: 'Insulation', sub: '', h: 75, heat: null, work: 'W4', workDir: 1, tip: 'Adiabatic compression: insulated again; work W4 warms the gas from Tc back to Th with no heat flow, returning it to state M and closing the cycle.' }
];

// deterministic stipple
var dots = [];
(function () { var s = 12345; for (var i = 0; i < 800; i++) { s = (s * 1103515245 + 12345) & 0x7fffffff; var a = s / 0x7fffffff; s = (s * 1103515245 + 12345) & 0x7fffffff; dots.push([a, s / 0x7fffffff]); } })();

var panelsGroup = draw.group();

function arrow(g, x1, y1, x2, y2, color, wdt) {
  g.line(x1, y1, x2, y2).stroke({ color: color, width: wdt, linecap: 'round' });
  var ang = Math.atan2(y2 - y1, x2 - x1);
  var hl = 4 + wdt * 1.1;
  g.polygon([
    [x2, y2],
    [x2 - hl * Math.cos(ang - 0.45), y2 - hl * Math.sin(ang - 0.45)],
    [x2 - hl * Math.cos(ang + 0.45), y2 - hl * Math.sin(ang + 0.45)]
  ].map(function (p) { return p[0] + ',' + p[1]; }).join(' ')).fill(color);
}

function drawPanels() {
  panelsGroup.clear();
  var activeIdx = steps.indexOf(state.step);
  var wantIso = (state.contact === 'Isothermal (reservoir)');
  var top = 14, blockH = 330, panelW = 175, gap = 18, cylW = 64;
  var cylTop = top + 72, cylH = 168;
  var cylBot = cylTop + cylH;

  for (var i = 0; i < 4; i++) {
    var m = stepMeta[i];
    var x0 = 10 + i * (panelW + gap);
    var active = (i === activeIdx);
    var matchBoundary = (m.boundary === 'iso') === wantIso;
    var g = panelsGroup.group().opacity(active ? 1 : (matchBoundary ? 0.8 : 0.55));
    (function (idx, gg) {
      gg.css('cursor', 'pointer');
      gg.on('mousemove', function (e) { showTooltip(stepMeta[idx].label + ' ' + stepMeta[idx].name, e); });
      gg.on('mouseleave', function () { hideTooltip(); });
      gg.on('click', function () { showPopup(stepMeta[idx].label + ' ' + stepMeta[idx].name, stepMeta[idx].tip); update_stepState(steps[idx]); });
    })(i, g);

    // surroundings block — saturated colors as in the source
    var blk = g.rect(panelW, blockH).move(x0, top).fill(m.color).stroke({ color: '#999', width: 1 });
    if (matchBoundary && !active) blk.stroke({ color: (m.boundary === 'iso' ? '#a03030' : '#8a7a55'), width: 2.5 });
    if (active) blk.stroke({ color: '#2e8b2e', width: 3 });

    // cylinder walls (open top, white cut into the block)
    var cx = x0 + panelW / 2 - cylW / 2;
    var stemX = x0 + panelW / 2;
    g.rect(cylW, cylH + 26).move(cx, cylTop - 26).fill('#fff').stroke('none');
    g.line(cx, cylTop - 26, cx, cylBot).stroke({ color: '#555', width: 1.5 });
    g.line(cx + cylW, cylTop - 26, cx + cylW, cylBot).stroke({ color: '#555', width: 1.5 });
    g.line(cx, cylBot, cx + cylW, cylBot).stroke({ color: '#555', width: 1.5 });

    // gas with stipple
    var gh = m.h;
    var gy = cylBot - gh;
    g.rect(cylW - 4, gh).move(cx + 2, gy).fill('#dcdcdc');
    for (var d = 0; d < dots.length; d++) {
      var dx = cx + 6 + dots[d][0] * (cylW - 12), dy = gy + 4 + dots[d][1] * (gh - 8);
      if (dy < cylBot - 4) g.circle(2.2).center(dx, dy).fill('#777');
    }

    // piston: darker gray cap + short stubby handle tab
    g.rect(cylW - 2, 10).move(cx + 1, gy - 10).fill('#a8a8a8').stroke({ color: '#666', width: 1 });
    g.rect(9, 16).move(stemX - 4.5, gy - 26).fill('#b5b5b5').stroke({ color: '#777', width: 1 });

    // green work arrow beside the piston
    var wLen = 40;
    var wy = gy - 44;
    var wy2 = wy + m.workDir * wLen;
    var wCol = active ? '#2e8b2e' : '#77aa77';
    arrow(g, stemX - 20, wy, stemX - 20, wy2, wCol, active ? 3 : 2);
    g.plain(m.work).font({ size: 15, weight: 'bold', family: 'sans-serif' }).fill(wCol)
      .attr({ 'text-anchor': 'middle', 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' })
      .center(stemX - 20, wy2 + (m.workDir < 0 ? -14 : 14));

    // thick gray heat arrow through the block bottom — steps 1 & 3 only
    if (m.heat) {
      var baseY = cylBot + 2, endY = cylBot + 56;
      var qcX = stemX + 22;
      if (m.heatDir < 0) {
        arrow(g, stemX, endY, stemX, baseY, '#777', 5.5);
        g.plain('Qh').font({ size: 16, weight: 'bold', family: 'sans-serif' }).fill('#444')
          .attr({ 'text-anchor': 'middle', 'paint-order': 'stroke', stroke: m.color, 'stroke-width': 3, 'stroke-linejoin': 'round' })
          .center(stemX + 34, baseY + 26);
      } else {
        arrow(g, qcX, baseY, qcX, endY, '#777', 5.5);
        g.plain('Qc').font({ size: 16, weight: 'bold', family: 'sans-serif' }).fill('#444')
          .attr({ 'text-anchor': 'middle', 'paint-order': 'stroke', stroke: m.color, 'stroke-width': 3, 'stroke-linejoin': 'round' })
          .center(qcX + 30, baseY + 26);
      }
    }

    // block labels centered at the block bottom (ample padding below cylinder)
    var labelCX = x0 + panelW / 2;
    var blockLabelY = top + blockH - (m.sub ? 40 : 26);
    g.plain(m.block).font({ size: 15, weight: 'bold', family: 'sans-serif' }).fill('#2a2a2a')
      .attr({ 'text-anchor': 'middle', 'paint-order': 'stroke', stroke: m.color, 'stroke-width': 3, 'stroke-linejoin': 'round' })
      .center(labelCX, blockLabelY);
    if (m.sub) {
      g.plain(m.sub).font({ size: 12, family: 'sans-serif' }).fill('#2a2a2a')
        .attr({ 'text-anchor': 'middle', 'paint-order': 'stroke', stroke: m.color, 'stroke-width': 3, 'stroke-linejoin': 'round' })
        .center(labelCX, top + blockH - 20);
    }

    // bold caption under the block
    g.plain(m.label).font({ size: 14, weight: 'bold', family: 'sans-serif' }).fill('#000').attr({ 'text-anchor': 'middle' }).center(labelCX, top + blockH + 22);
    g.plain(m.name).font({ size: 14, weight: 'bold', family: 'sans-serif' }).fill('#000').attr({ 'text-anchor': 'middle' }).center(labelCX, top + blockH + 40);
    g.plain(m.trans).font({ size: 14, weight: 'bold', family: 'sans-serif' }).fill('#000').attr({ 'text-anchor': 'middle' }).center(labelCX, top + blockH + 58);
  }
}

function render() { drawPanels(); }

function update_stepState(v) {
  state.step = v;
  document.getElementById('stepStateInput').value = v;
  var i = steps.indexOf(v);
  state.contact = (i === 0 || i === 2) ? 'Isothermal (reservoir)' : 'Adiabatic (insulated)';
  document.getElementById('thermalContactInput').checked = (state.contact === 'Isothermal (reservoir)');
  render();
}

// Toggling the boundary condition NEVER changes the selected step — it only
// re-emphasizes which panels share that boundary type.
function toggle_thermalContact(on) {
  state.contact = on ? 'Isothermal (reservoir)' : 'Adiabatic (insulated)';
  render();
  document.getElementById('demoNarration').textContent = on
    ? 'Isothermal boundary: heat can cross only while the cylinder sits in a reservoir — panels 1 and 3 (Qh in at Th, Qc out at Tc). The selected step is unchanged.'
    : 'Adiabatic boundary: inside insulation (panels 2 and 4) no heat flows; temperature changes come entirely from work. The selected step is unchanged.';
}

function applyStep(i) {
  curStep = ((i % demoSteps.length) + demoSteps.length) % demoSteps.length;
  var s = demoSteps[curStep];
  document.getElementById('demoNarration').textContent = s.title + ' — ' + s.narration;
  document.getElementById('stepLabel').textContent = (curStep + 1) + ' / ' + demoSteps.length;
  state.step = s.state.stepState;
  state.contact = s.state.thermalContact;
  document.getElementById('stepStateInput').value = state.step;
  document.getElementById('thermalContactInput').checked = (state.contact === 'Isothermal (reservoir)');
  render();
}
function nextStep() { applyStep(curStep + 1); }
function prevStep() { applyStep(curStep - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

